/**
 * Pairwise A/B comparison of two bench results files (iteration engine, blueprint E).
 *
 * Takes the answers already generated by two bench runs and asks the founder-calibrated
 * judge "which would he rate higher?" per matching case — judged in both orders so
 * position bias resolves to a tie. Far more decision-reliable than comparing absolute
 * 0–10 scores across runs, and costs only judge calls (no new answers).
 *
 * Run:  npm run engineer:bench:pairwise -- --a=results/old.json --b=results/new.json
 * Args: --a=path --b=path   (bench results files; paths relative to repo root ok)
 *       --set=path          (benchmark set for judge exemplars; default benchmark-set.json)
 *       --limit=N           (first N shared cases)
 *       --delay=8           (seconds between pairs; judge calls are small)
 */
import fs from "node:fs/promises";
import path from "node:path";
import {
  judgeEngineerAnswerPairwise,
  type JudgeExemplar,
} from "@/lib/engineerFeedback/calibratedJudge";
import { sleepMs } from "@/lib/openAiRetry";
import type { BenchmarkSet } from "./build-benchmark-set";

type ResultsFile = {
  label: string;
  results: Array<{ id: string; question: string; answer: string | null }>;
};

function arg(name: string): string | null {
  return process.argv.find((a) => a.startsWith(`--${name}=`))?.slice(name.length + 3) ?? null;
}

async function main() {
  const aPath = arg("a");
  const bPath = arg("b");
  if (!aPath || !bPath) throw new Error("Pass --a=<results.json> --b=<results.json>");
  const setPath = arg("set") ?? path.join(process.cwd(), "scripts/engineer-bench/benchmark-set.json");
  const limit = arg("limit") ? Number(arg("limit")) : Infinity;
  const delayMs = (arg("delay") ? Number(arg("delay")) : 8) * 1000;

  const a = JSON.parse(await fs.readFile(path.resolve(aPath), "utf8")) as ResultsFile;
  const b = JSON.parse(await fs.readFile(path.resolve(bPath), "utf8")) as ResultsFile;
  const set = JSON.parse(await fs.readFile(setPath, "utf8")) as BenchmarkSet;
  const exemplars: JudgeExemplar[] = set.exemplars ?? [];

  const bById = new Map(b.results.map((r) => [r.id, r]));
  const pairs = a.results
    .filter((r) => r.answer && bById.get(r.id)?.answer)
    .slice(0, Number.isFinite(limit) ? limit : undefined);
  if (pairs.length === 0) throw new Error("No shared answered cases between the two files");

  console.log(
    `Pairwise: A="${a.label}" vs B="${b.label}" · ${pairs.length} shared cases · ${exemplars.length} exemplars`
  );

  let winsA = 0;
  let winsB = 0;
  let ties = 0;
  let agreed = 0;
  const rows: Array<{ id: string; winner: string; agreed: boolean; rationale: string }> = [];

  for (let i = 0; i < pairs.length; i++) {
    if (i > 0 && delayMs > 0) await sleepMs(delayMs);
    const ra = pairs[i];
    const rb = bById.get(ra.id)!;
    process.stdout.write(`[${i + 1}/${pairs.length}] ${ra.id}… `);
    const v = await judgeEngineerAnswerPairwise({
      question: ra.question,
      answerA: ra.answer!,
      answerB: rb.answer!,
      exemplars,
    });
    if (v.winner === "A") winsA++;
    else if (v.winner === "B") winsB++;
    else ties++;
    if (v.agreedBothOrders) agreed++;
    console.log(`${v.winner === "tie" ? "tie" : `winner=${v.winner}`}${v.agreedBothOrders ? "" : " (orders disagreed)"}`);
    rows.push({
      id: ra.id,
      winner: v.winner,
      agreed: v.agreedBothOrders,
      rationale: v.rationaleFirstOrder,
    });
  }

  console.log(`\n--- Pairwise verdict ---`);
  console.log(`A "${a.label}": ${winsA} wins`);
  console.log(`B "${b.label}": ${winsB} wins`);
  console.log(`Ties: ${ties} · both-order agreement: ${agreed}/${pairs.length}`);
  const decisive = winsA + winsB;
  if (decisive > 0) {
    console.log(`Win rate among decisive: A ${(100 * winsA / decisive).toFixed(0)}% · B ${(100 * winsB / decisive).toFixed(0)}%`);
  }

  const outPath = path.join(
    process.cwd(),
    "scripts/engineer-bench/results",
    `pairwise-${a.label}-vs-${b.label}-${new Date().toISOString().replace(/[:.]/g, "-")}.json`
  );
  await fs.writeFile(
    outPath,
    JSON.stringify({ a: a.label, b: b.label, winsA, winsB, ties, agreed, rows }, null, 2)
  );
  console.log(`Saved: ${outPath}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
